mapper.select:
SELECT  FROM workflow
WHERE workspace_id = #{workspaceId} AND id = #{id}
FOR UPDATE

SELECT  FROM workflow
WHERE workspace_id = #{workspaceId} AND legacy_rule_id = #{legacyRuleId}
FOR UPDATE

SELECT ,
  (w.intake_paused_by_id = #{userId}
    OR EXISTS (
      SELECT 1 FROM workflow_recipe_origin origin
      WHERE origin.workspace_id = w.workspace_id
        AND origin.workflow_id = w.id
        AND origin.installed_by_id = #{userId}
    )
    OR EXISTS (
      SELECT 1 FROM workflow_invocation invocation
      WHERE invocation.workspace_id = w.workspace_id
        AND invocation.workflow_id = w.id
        AND invocation.requested_by_id = #{userId}
    )
    OR EXISTS (
      SELECT 1
      FROM workflow_intervention intervention
      JOIN workflow_run wr
        ON wr.workspace_id = intervention.workspace_id
       AND wr.id = intervention.workflow_run_id
      WHERE intervention.workspace_id = w.workspace_id
        AND wr.workflow_id = w.id
        AND intervention.owner_user_id = #{userId}
    )) AS operations_user_affected
FROM workflow w
WHERE w.created_by_id = #{userId}
   OR w.updated_by_id = #{userId}
   OR w.draft_run_as_user_id = #{userId}
   OR w.intake_paused_by_id = #{userId}
   OR EXISTS (
     SELECT 1 FROM workflow_version v
     WHERE v.workspace_id = w.workspace_id
       AND v.workflow_id = w.id
       AND v.id = w.active_version_id
       AND (v.created_by_id = #{userId}
         OR v.published_by_id = #{userId}
         OR v.run_as_user_id = #{userId})
   )
   OR EXISTS (
     SELECT 1 FROM rule r
     WHERE r.workspace_id = w.workspace_id
       AND r.id = w.legacy_rule_id
       AND (r.created_by_id = #{userId} OR r.run_as_user_id = #{userId})
   )
   OR EXISTS (
     SELECT 1 FROM workflow_recipe_origin origin
     WHERE origin.workspace_id = w.workspace_id
       AND origin.workflow_id = w.id
       AND origin.installed_by_id = #{userId}
   )
   OR EXISTS (
     SELECT 1 FROM workflow_invocation invocation
     WHERE invocation.workspace_id = w.workspace_id
       AND invocation.workflow_id = w.id
       AND invocation.requested_by_id = #{userId}
   )
   OR EXISTS (
     SELECT 1
     FROM workflow_intervention intervention
     JOIN workflow_run wr
       ON wr.workspace_id = intervention.workspace_id
      AND wr.id = intervention.workflow_run_id
     WHERE intervention.workspace_id = w.workspace_id
       AND wr.workflow_id = w.id
       AND intervention.owner_user_id = #{userId}
   )
ORDER BY w.workspace_id, w.id

SELECT 
FROM rule r
WHERE r.workspace_id = #{workspaceId}
  AND NOT EXISTS (
    SELECT 1 FROM workflow w
    WHERE w.workspace_id = #{workspaceId}
      AND w.legacy_rule_id = r.id
  )
ORDER BY r.id

SELECT COUNT(*)
FROM rule r
WHERE r.workspace_id = #{workspaceId}
  AND NOT EXISTS (
    SELECT 1 FROM workflow w
    WHERE w.workspace_id = #{workspaceId}
      AND w.legacy_rule_id = r.id
  )

SELECT r.id
FROM rule r
WHERE r.workspace_id = #{workspaceId}
  AND NOT EXISTS (
    SELECT 1 FROM workflow w
    WHERE w.workspace_id = #{workspaceId}
      AND w.legacy_rule_id = r.id
  )
ORDER BY r.id
LIMIT 1

mapper.update:
UPDATE workflow
SET legacy_rule_id = #{legacyRuleId},
    active_version_id = #{activeVersionId},
    runtime_generation = runtime_generation + 1,
    updated_by_id = #{updatedById}
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND archived_at IS NULL
  AND draft_revision = #{expectedRevision}
  AND legacy_rule_id IS NULL
  AND active_version_id IS NULL

UPDATE workflow
SET active_version_id = #{activeVersionId},
    runtime_owner = 'canonical',
    runtime_generation = runtime_generation + 1,
    updated_by_id = #{updatedById}
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND archived_at IS NULL
  AND runtime_owner = 'legacy'
  AND draft_revision = #{expectedRevision}
  AND legacy_rule_id IS NULL
  AND active_version_id IS NULL

UPDATE workflow
SET active_version_id = #{activeVersionId},
    runtime_generation = runtime_generation + 1,
    updated_by_id = #{updatedById}
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND archived_at IS NULL
  AND draft_revision = #{expectedRevision}
  AND legacy_rule_id = #{expectedLegacyRuleId}
  AND active_version_id = #{expectedActiveVersionId}

UPDATE workflow
SET active_version_id = #{activeVersionId},
    runtime_generation = runtime_generation + 1,
    updated_by_id = #{updatedById}
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND archived_at IS NULL
  AND runtime_owner = 'canonical'
  AND active_version_id = #{expectedActiveVersionId}
  AND draft_revision = #{expectedRevision}

UPDATE workflow
SET enabled = #{enabled},
    runtime_generation = runtime_generation + 1,
    updated_by_id = #{updatedById}
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND archived_at IS NULL
  AND enabled <> #{enabled}

UPDATE workflow
SET name = #{workflow.name},
    description = #{workflow.description},
    enabled = #{workflow.enabled},
    draft_revision = draft_revision + 1,
    draft_record_type = #{workflow.draftRecordType},
    draft_execution_mode = #{workflow.draftExecutionMode},
    draft_run_as_user_id = #{workflow.draftRunAsUserId},
    draft_definition_json = #{workflow.draftDefinitionJson},
    draft_canvas_json = #{workflow.draftCanvasJson},
    active_version_id = #{activeVersionId},
    runtime_generation = runtime_generation + 1,
    updated_by_id = #{workflow.updatedById}
WHERE workspace_id = #{workflow.workspaceId}
  AND id = #{workflow.id}
  AND archived_at IS NULL
  AND legacy_rule_id = #{expectedLegacyRuleId}
  AND active_version_id = #{expectedActiveVersionId}
  AND draft_revision = #{expectedRevision}

UPDATE workflow
SET enabled = FALSE,
    archived_at = CURRENT_TIMESTAMP,
    runtime_generation = runtime_generation + 1,
    updated_by_id = #{updatedById}
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND archived_at IS NULL

UPDATE workflow
SET enabled = FALSE,
    archived_at = NULL,
    runtime_generation = runtime_generation + 1,
    updated_by_id = #{updatedById}
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND archived_at IS NOT NULL

UPDATE workflow
SET intake_paused_at = CASE WHEN #{paused} THEN CURRENT_TIMESTAMP(6) ELSE NULL END,
    intake_paused_by_id = CASE WHEN #{paused} THEN #{updatedById} ELSE NULL END,
    updated_by_id = #{updatedById}
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND archived_at IS NULL
  AND ((#{paused} AND intake_paused_at IS NULL)
    OR (NOT #{paused} AND intake_paused_at IS NOT NULL))

UPDATE workflow
SET runtime_owner = #{runtimeOwner}, updated_by_id = #{updatedById}
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND active_version_id = #{expectedActiveVersionId}
  AND runtime_owner = #{expectedOwner}
  AND archived_at IS NULL

UPDATE workflow
SET legacy_rule_id = #{legacyRuleId},
    runtime_owner = #{runtimeOwner},
    updated_by_id = #{updatedById}
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND active_version_id = #{expectedActiveVersionId}
  AND legacy_rule_id IS NULL
  AND runtime_owner = #{expectedOwner}
  AND archived_at IS NULL

UPDATE workflow
SET draft_run_as_user_id = IF(draft_run_as_user_id = #{userId}, NULL, draft_run_as_user_id),
    created_by_id = IF(created_by_id = #{userId}, NULL, created_by_id),
    updated_by_id = IF(updated_by_id = #{userId}, NULL, updated_by_id)
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND (draft_run_as_user_id = #{userId}
    OR created_by_id = #{userId}
    OR updated_by_id = #{userId})

UPDATE workflow
SET active_version_id = #{activeVersionId},
    runtime_generation = runtime_generation + 1,
    updated_by_id = #{updatedById}
WHERE workspace_id = #{workspaceId} AND id = #{id}
